<?php
require_once __DIR__.'/includes/auth.php';require_permission('accounts');require_once __DIR__.'/mailer.php';$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$action=$_POST['form_action']??'';$stmt=$pdo->prepare('SELECT * FROM resident_applications WHERE id=? AND status=\'Pending\'');$stmt->execute([$id]);$app=$stmt->fetch();if(!$app){flash('error','That application is no longer pending.');redirect('resident_applications.php');}if($action==='reject'){$reason=trim($_POST['rejection_reason']??'');if($reason==='')$reason='Application did not meet the barangay review requirements.';$pdo->prepare('UPDATE resident_applications SET status=\'Rejected\',rejection_reason=?,reviewed_by=?,reviewed_at=NOW() WHERE id=?')->execute([$reason,current_user()['id'],$id]);audit_action('resident_application_rejected','resident_applications',$id,$reason);flash('success','Application rejected with a recorded reason.');redirect('resident_applications.php');}if($action==='approve'){$existing=$pdo->prepare('SELECT id FROM users WHERE username=? OR email=?');$existing->execute([$app['username'],$app['email']]);if($existing->fetch()){flash('error','The applicant username or email is now already in use. Resolve the duplicate before approving.');redirect('resident_applications.php');}$pdo->beginTransaction();try{$barangayId='BRG-'.random_int(100000,999999);$pdo->prepare('INSERT INTO residents (barangay_id,full_name,address,age,sector,household,civil_status,contact_number,status) VALUES (?,?,?,?,?,?,?,? ,\'Active\')')->execute([$barangayId,$app['full_name'],$app['address'],$app['age'],$app['sector'],$app['household'],$app['civil_status'],$app['contact_number']]);$residentId=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO users (resident_id,full_name,email,username,password_hash,role,account_status,account_expires_at) VALUES (?,?,?,?,?,\'resident\',\'active\',DATE_ADD(CURDATE(),INTERVAL 365 DAY))')->execute([$residentId,$app['full_name'],$app['email'],$app['username'],$app['password_hash']]);$pdo->prepare('UPDATE resident_applications SET status=\'Approved\',reviewed_by=?,reviewed_at=NOW() WHERE id=?')->execute([current_user()['id'],$id]);$pdo->commit();audit_action('resident_application_approved','resident_applications',$id,$barangayId);send_notification($app['email'],'Resident portal application approved','<p>Your resident portal application was approved. Your Barangay ID is <strong>'.h($barangayId).'</strong>. You may now sign in with your username, password, and email OTP.</p>');flash('success','Application approved and resident portal access created.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log($e->getMessage());flash('error','The application could not be approved. No records were created.');}redirect('resident_applications.php');}}
$apps=$pdo->query('SELECT a.*,u.full_name AS reviewer FROM resident_applications a LEFT JOIN users u ON u.id=a.reviewed_by ORDER BY FIELD(a.status,\'Pending\',\'Rejected\',\'Approved\'),a.created_at DESC')->fetchAll();$pageTitle='Resident applications';$activePage='applications';require __DIR__.'/partials/header.php';
?><section class="section-heading"><div><div class="eyebrow">Access / Resident onboarding</div><h1>Resident applications</h1><p>Review self-service account requests, record rejection reasons, and approve only after identity checks.</p></div><span class="view-pill"><i></i> <?= count(array_filter($apps,fn($a)=>$a['status']==='Pending')) ?> pending</span></section><section class="panel table-panel"><div class="table-toolbar"><div><div class="eyebrow">Application queue</div><h2>Resident access requests</h2></div><span class="muted"><?= count($apps) ?> applications</span></div><div class="table-wrap"><table><thead><tr><th>Applicant</th><th>Contact / profile</th><th>Submitted</th><th>Status</th><th>Review</th></tr></thead><tbody><?php foreach($apps as $app): ?><tr><td><strong><?= h($app['full_name']) ?></strong><small class="cell-subtext mono">@<?= h($app['username']) ?></small></td><td><?= h($app['email']) ?><small class="cell-subtext"><?= h($app['address']) ?> · <?= h($app['sector']) ?></small></td><td class="muted"><?= h(date('M d, Y h:i A',strtotime($app['created_at']))) ?></td><td><span class="status-pill <?= h(strtolower($app['status'])) ?>"><i></i><?= h($app['status']) ?></span><?php if($app['status']==='Rejected'): ?><small class="cell-subtext"><?= h($app['rejection_reason']) ?></small><?php endif; ?></td><td><?php if($app['status']==='Pending'): ?><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="id" value="<?= h($app['id']) ?>"><button class="primary-button" name="form_action" value="approve" onclick="return confirm('Approve this application and create resident portal access?')">Approve</button> <button class="danger-link" name="form_action" value="reject" onclick="var r=prompt('Reason for rejection:');if(!r)return false;this.form.rejection_reason.value=r;return confirm('Reject this application?')">Reject</button><input type="hidden" name="rejection_reason" value=""></form><?php else: ?><span class="muted">Reviewed by <?= h($app['reviewer']??'staff') ?></span><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$apps): ?><tr><td colspan="5" class="empty-state">No applications yet.</td></tr><?php endif; ?></tbody></table></div></section><?php require __DIR__.'/partials/footer.php'; ?>
